import axios from 'axios';

const API_BASE = 'http://127.0.0.1:8000/api';

const client = axios.create({
  baseURL: API_BASE,
  timeout: 10000,
});

export const olap = {
  // Metadata
  getCustomerTypes: () => client.get('/metadata/customer-types'),
  getProducts: (limit = 100) => client.get('/metadata/products', { params: { limit } }),
  getStores: () => client.get('/metadata/stores'),
  getCities: () => client.get('/metadata/cities'),

  // Sales - Drill Down
  getSalesByYear: () => client.get('/sales/by-year'),
  getSalesByQuarter: (year) => client.get('/sales/by-quarter', { params: { year } }),
  getSalesByMonth: (year) => client.get('/sales/by-month', { params: { year } }),

  // Sales - Slice/Dice
  getSalesByProduct: (year) => client.get('/sales/by-product', { params: { year } }),
  getSalesByCustomerType: () => client.get('/sales/by-customer-type'),
  getSalesMonthByCustType: (year) => client.get('/sales/month-by-custtype', { params: { year } }),
  getSalesProductByCustType: (year) => client.get('/sales/product-by-custtype', { params: { year } }),

  // Inventory - Drill Down
  getInventoryByYear: () => client.get('/inventory/by-year'),
  getInventoryByQuarter: (year) => client.get('/inventory/by-quarter', { params: { year } }),
  getInventoryByMonth: (year) => client.get('/inventory/by-month', { params: { year } }),

  // Inventory - Slice/Dice
  getInventoryByProduct: () => client.get('/inventory/by-product'),
  getInventoryByStore: () => client.get('/inventory/by-store'),
  getInventoryByCity: () => client.get('/inventory/by-city'),
  getInventoryMonthProductStore: (year, store_key) => 
    client.get('/inventory/month-product-store', { params: { year, store_key } }),
  getInventoryProductByCity: (product_key) => 
    client.get('/inventory/product-by-city', { params: { product_key } }),

  // Drill Across
  getCrossAnalysisSalesVsInventoryByProduct: () => 
    client.get('/cross-analysis/sales-vs-inventory-by-product'),
  getCrossAnalysisSalesVsInventoryByMonth: (year) => 
    client.get('/cross-analysis/sales-vs-inventory-by-month', { params: { year } }),

  // Drill Through
  drillThroughSales: (year, month, customer_type, product_key, limit = 50, offset = 0) => 
    client.get('/drill-through/sales', { 
      params: { year, month, customer_type, product_key, limit, offset } 
    }),
  drillThroughInventory: (year, month, store_key, product_key, limit = 50, offset = 0) => 
    client.get('/drill-through/inventory', { 
      params: { year, month, store_key, product_key, limit, offset } 
    }),

  // Summary
  getSalesTotal: () => client.get('/summary/sales-total'),
  getInventoryTotal: () => client.get('/summary/inventory-total'),
};

export default client;
